INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (146,10,117,'SUM, AVERAGE, MAX, MIN, IF\n',NULL,5,'2026-09-14 23:42:15.000','2026-09-14 23:42:29.000','Jawaban sangat tepat, siswa berhasil menyebutkan kelima fungsi Excel sesuai dengan kebutuhan yang diminta.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (147,10,108,'Data terstruktur adalah susunan data yang rapi dan berurutan dengan format tertentu.\nContoh: Tabel peserta didik (dengan nama, usia, dll)',NULL,5,'2026-09-14 23:42:15.000','2026-09-14 23:42:29.000','Siswa mampu menjelaskan konsep data terstruktur dengan kalimat sendiri dan memberikan contoh yang relevan.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (148,10,112,'Misalnya mau hitung dari A1 ke A7\n=MAX(A1:A7)\n=MIN(A1:A7)',NULL,5,'2026-09-14 23:42:15.000','2026-09-14 23:42:29.000','Penulisan rumus MAX dan MIN sudah benar beserta contoh rentang selnya.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (149,10,126,'=SUM(B2:B15)',NULL,6,'2026-09-14 23:42:15.000','2026-09-14 23:42:29.000','Penulisan rumus SUM sudah tepat sesuai dengan rentang sel yang diminta pada soal.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (150,10,114,'=IF(C2>=75,\"Lulus\",\"Tidak Lulus)',NULL,5,'2026-09-14 23:42:15.000','2026-09-14 23:42:29.000','Konsep rumus IF sudah benar, namun terdapat sedikit kesalahan sintaksis berupa tanda petik penutup yang kurang pada teks \"Tidak Lulus\".');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (151,10,121,'=AVERAGE(B2:B6)',NULL,2.5,'2026-09-14 23:42:15.000','2026-09-14 23:42:29.000','Siswa sudah tepat menggunakan fungsi AVERAGE, namun rujukan sel salah (menggunakan B2:B6 padahal pada soal data berada pada A1:A5).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (152,10,125,'Character\nData yang berisi satu karakter saja. Contohnya mau buat data terstruktur untuk kelamin isi \"L\" atau \"P\"\n\nInteger\nData yang berisi bilangan bulat, positif maupun negatif. Contohnya nilai sebuah siswa di rapor yang \"89\"',NULL,5,'2026-09-14 23:42:15.000','2026-09-14 23:42:29.000','Siswa menjelaskan 2 tipe data (Character dan Integer) beserta pengertian dan contoh penerapan dengan sangat baik.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (153,10,113,'SUM = Menjumlahkan semua bilangan dalam range yang terinput\nAVERAGE = Menghitung rata-rata bilangan dalam suatu range yang terinput\nMIN = Mencari nilai bilangan terkecil dalam sebuah range\nMAX = Mencari nilai bilangan terbesar dalam sebuah range',NULL,6,'2026-09-14 23:42:15.000','2026-09-14 23:42:29.000','Penjelasan fungsi SUM, AVERAGE, MIN, dan MAX lengkap dan akurat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (154,10,116,'Karena data terstruktur bisa mengorganisasi persoalan (peserta didik, daftar belanja) dengan gampang.\nDan Microsoft Excel adalah tempat tergampang untuk membuat sebuah data terstruktur.',NULL,3,'2026-09-14 23:42:15.000','2026-09-14 23:42:29.000','Jawaban cukup relevan, namun belum menjelaskan secara spesifik manfaat penggunaan \'fungsi/formula\' Excel dalam efisiensi dan otomatisasi perhitungan data.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (155,10,115,'Ani: Lulus (lebih dari 75)\nBeni: Tidak Lulus (nilai lebih rendah daripada 75 jadi tidak lulus)\nCici: Lulus (nilainya tepat 75)\nDoni: Lulus (lebih dari 75)',NULL,5,'2026-09-14 23:42:15.000','2026-09-14 23:42:29.000','Siswa berhasil menentukan status kelulusan keempat siswa sesuai logika syarat batas nilai (>=75) dengan benar.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (156,21,69,'B',1,NULL,'2026-09-14 23:45:04.000','2026-09-14 23:45:04.000',NULL);
