INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (216,21,124,'range adalah kumpulan dari beberapa cell \ncontoh D4;D6',NULL,4,'2026-09-14 23:45:04.000','2026-09-14 23:45:18.000','Siswa memahami pengertian Range dengan baik, namun contoh penulisan menggunakan titik koma (;) alih-alih titik dua (:).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (217,21,127,'if digunakan untuk memprediksi sesuatu berdasarkan informasi yang di berikan\ncontoh mencari apakah siswa ini lulus atau tidak lulus',NULL,3.5,'2026-09-14 23:45:04.000','2026-09-14 23:45:18.000','Contoh kasus sudah sesuai, namun penjelasan cara kerja fungsi IF kurang akurat karena IF berfungsi mengevaluasi syarat/kondisi logika.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (218,21,125,'string untuk  menulis kata yang ada banyak tanda baca nya contoh \"A\"\ninteger untuk menulis bil bulat ',NULL,3.5,'2026-09-14 23:45:04.000','2026-09-14 23:45:18.000','Siswa menyebutkan tipe data String dan Integer dengan penjelasan yang cukup, tetapi contoh penerapan dalam kehidupan sehari-hari belum diberikan secara spesifik.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (219,21,115,'Ani =if(80>=75,\"lulus\",\"tidak lulus\"))\nBeni =if(60>=75,\"lulus\",tidak lulus\"))\nDoni =if(90>=75\"lulus\",\"tidak lulus\"))',NULL,2.5,'2026-09-14 23:45:04.000','2026-09-14 23:45:18.000','Siswa memahami konsep logika IF, namun data Cici terlewat serta terdapat beberapa kesalahan penulisan sintaks rumus.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (220,21,123,'UKURAN FRONT\nUBAH WARNA\nMELETAKKAN HURUF',NULL,1,'2026-09-14 23:45:04.000','2026-09-14 23:45:18.000','Jawaban kurang tepat karena siswa menyebutkan fitur pengolah format teks/font, bukan bagian utama antarmuka Excel.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (221,21,110,'=SUM(80,75,90,65,85)',NULL,2.5,'2026-09-14 23:45:04.000','2026-09-14 23:45:18.000','Siswa menggunakan fungsi SUM, namun memasukkan data angka secara manual dengan satu angka yang salah (65 alih-alih 70) dan tidak menggunakan referensi sel.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (222,21,112,'=MAX(......)\n=MIN(.......)',NULL,2.5,'2026-09-14 23:45:04.000','2026-09-14 23:45:18.000','Siswa sudah benar memilih fungsi MAX dan MIN, tetapi tidak melengkapi argumen range sel dalam rumus.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (223,21,118,'sum =memuat total nilai\naverage = mencari nilai rata rata\nmin = mencari nilai terrendah\nmax = mencari nilai terbesar',NULL,5,'2026-09-14 23:45:04.000','2026-09-14 23:45:18.000','Penjelasan untuk fungsi SUM, AVERAGE, MIN, dan MAX sudah tepat, lengkap, dan relevan.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (224,21,114,'=if(C2>=75,\"lulus\",if(C2<75,\"tidak lulus\"))',NULL,5.5,'2026-09-14 23:45:04.000','2026-09-14 23:45:18.000','Rumus bernilai benar dan dapat berfungsi, meskipun struktur IF bersarang yang digunakan sebenarnya tidak perlu.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (225,21,119,'=sum(B2:B6)\n=AVERAGE(B2:B6)\n=MIN(B2:B6)\n=MAX(B2:B6)',NULL,5,'2026-09-14 23:45:04.000','2026-09-14 23:45:18.000','Semua formula untuk total, rata-rata, nilai terendah, dan nilai tertinggi dituliskan dengan sangat tepat menggunakan rentang sel yang benar.');
