INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (286,18,109,'angka:digunakan untuk menghitung data\nteks:\nboolean:tipe data logika yang hanya memiliki 2 kemungkinan yaitu true dan false',NULL,2,'2026-09-14 23:45:52.000','2026-09-14 23:46:10.000','Siswa menyebutkan pengertian data angka dan boolean secara singkat, tetapi tidak mengisi penjelasan data teks dan tidak mencantumkan contoh untuk ketiganya.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (287,18,126,'=sum(2:15)',NULL,2,'2026-09-14 23:45:52.000','2026-09-14 23:46:10.000','Siswa sudah memahami penggunaan fungsi SUM, namun penulisan rentang sel belum tepat karena tidak mencantumkan abjad kolom (seharusnya =SUM(B2:B15)).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (288,18,108,'data terstruktur adalah data yang di kelola dan disimpan di komputer supaya bisa  melihat data yang sudah tersimpan.',NULL,1.5,'2026-09-14 23:45:52.000','2026-09-14 23:46:10.000','Penjelasan siswa masih terlalu umum dan belum mencakup karakteristik utama data terstruktur (seperti format rapi/tabel), serta tidak menyertakan contoh.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (289,18,110,'=sum(80:90)',NULL,1.5,'2026-09-14 23:45:52.000','2026-09-14 23:46:10.000','Siswa sudah menggunakan fungsi SUM, tetapi penulisan rentang nilai angka (=sum(80:90)) tidak sesuai dengan tata cara penulisan rumus Excel.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (290,18,112,'max dan min',NULL,1.5,'2026-09-14 23:45:52.000','2026-09-14 23:46:10.000','Siswa hanya menyebutkan nama fungsi saja (MAX dan MIN) tanpa menuliskan bentuk penulisan rumus/formula Excel yang lengkap beserta argumen selnya.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (291,18,120,'-supaya cara menghitungnya tidak salah.\n-cara menghitungnya lebih gampang dari penghitungan manual.',NULL,4.5,'2026-09-14 23:45:52.000','2026-09-14 23:46:10.000','Siswa berhasil memberikan 2 alasan yang relevan (menghindari kesalahan hitung dan lebih gampang/efisien), meskipun dapat diperjelas lebih lanjut.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (292,18,118,'sum : untuk menjumlahkan nilai\naverage: untuk mencari nilai rata-rata\nmin: mencari nilai terendah\nmax: mencari nilai tertinggi',NULL,5,'2026-09-14 23:45:52.000','2026-09-14 23:46:10.000','Jawaban sangat baik, tepat, dan lengkap dalam menjelaskan fungsi SUM, AVERAGE, MIN, dan MAX.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (293,18,122,'=min(a6;b2)',NULL,1,'2026-09-14 23:45:52.000','2026-09-14 23:46:10.000','Jawaban belum tepat. Untuk menghitung selisih nilai terbanyak dan tersedikit, seharusnya mengombinasikan pengurangan fungsi MAX dan MIN (misal =MAX(...)-MIN(...)).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (294,18,119,'=average(b2:b6)\n=min(b2:b6)\n=max(b2:b6)\ntotal=97',NULL,3.5,'2026-09-14 23:45:52.000','2026-09-14 23:46:10.000','Siswa menuliskan formula AVERAGE, MIN, dan MAX dengan sangat tepat, namun formula untuk total nilai (=SUM(B2:B6)) belum dituliskan.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (295,18,125,'float: menggunakan data angka pechan/desimal .    \ninteger: menggunakan data angka bulat tanpa desimal.',NULL,3.5,'2026-09-14 23:45:52.000','2026-09-14 23:46:10.000','Siswa menyebutkan dan menjelaskan dua tipe data (float dan integer) dengan benar, namun belum menyertakan contohnya dalam kehidupan sehari-hari.');
