INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (356,11,115,'Jadi Ani lulus\nBeni tidak lulus \nCici lulus \nDoni lulus',NULL,4,'2026-09-14 23:46:08.000','2026-09-14 23:46:28.000','Siswa menentukan status kelulusan tiap siswa dengan benar berdasarkan ketentuan, namun tidak menuliskan bentuk rumus IF Excel.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (357,11,122,'DATA STOK TOKO BUKU\n1. DAY 4= 200\n2. DAY 2= 150\n3. DAY 5= 140\n4. DAY 1= 120\n5. DAY 3= 90\n',NULL,1,'2026-09-14 23:46:08.000','2026-09-14 23:46:28.000','Siswa hanya mengurutkan data stok dan tidak menuliskan kombinasi formula Excel (=MAX()-MIN()) yang diminta.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (358,11,117,' SUM, AVERAGE, MAX, MIN, DAN IF',NULL,5,'2026-09-14 23:46:08.000','2026-09-14 23:46:28.000','Jawaban sangat tepat dan lengkap, menyebutkan kelima fungsi Excel sesuai dengan kebutuhan pada soal.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (359,11,116,'Karena microsoft excel gratis dan mudah di gunakan untuk pengguna dan lebih akurat dan lebih simpel ',NULL,2.5,'2026-09-14 23:46:08.000','2026-09-14 23:46:28.000','Siswa menjawab alasan akurasi dan kemudahan dengan benar, namun kurang tepat mengenai informasi lisensi Microsoft Excel.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (360,11,118,'sum berfungsi untuk menjumlahkan angka-angka \naverage berfungsi untuk menghitung rata-rata angka \nmin berfungsi untuk menghitung nilai terendah \nmax berfungsi untuk menghitung nilai tertinggi \n',NULL,5,'2026-09-14 23:46:08.000','2026-09-14 23:46:28.000','Penjelasan mengenai fungsi SUM, AVERAGE, MIN, dan MAX dituliskan dengan benar, jelas, dan lengkap.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (361,11,123,'Untuk  menyelesaikan soal',NULL,0,'2026-09-14 23:46:08.000','2026-09-14 23:46:28.000','Jawaban belum relevan, tidak menyebutkan bagian antarmuka Microsoft Excel maupun fungsinya.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (362,11,113,'jadi sum berfungsi untuk menjumlahkan angka-angka\naverage berfungsi untuk menghitung rata-rata \nmin berfungsi untuk menghitung nilai terendah \nmax berfungsi untuk menghitung nilai terbesar\n',NULL,6,'2026-09-14 23:46:08.000','2026-09-14 23:46:28.000','Penjelasan untuk seluruh fungsi SUM, AVERAGE, MIN, dan MAX sudah tepat dan benar.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (363,11,121,'=average(A1;A2;A3;A4;A5)',NULL,5,'2026-09-14 23:46:08.000','2026-09-14 23:46:28.000','Penulisan formula AVERAGE untuk menghitung rata-rata sudah benar dan sesuai sintaks Excel.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (364,11,124,'RANGE ADALAH PERTEMUAN ANTARA KOLOM DAN BARIS\n',NULL,0,'2026-09-14 23:46:08.000','2026-09-14 23:46:28.000','Konsep kurang tepat (definisi yang diberikan adalah definisi Cell) dan siswa tidak memberikan contoh penulisannya.');
