INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (426,24,125,'float : mengunakan data pecahan/desimal\nstring : menyipan file nilai2',NULL,2,'2026-09-15 00:00:25.000','2026-09-15 00:00:41.000','Siswa menyebutkan 2 tipe data dan mengerti konsep dasar float, namun penjelasan string kurang tepat dan tidak memberikan contoh dalam kehidupan sehari-hari.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (427,24,116,'karena membantu dalam menyipan file dan documen penting',NULL,1,'2026-09-15 00:00:25.000','2026-09-15 00:00:41.000','Jawaban kurang tepat karena hanya menyebutkan penyimpanan dokumen, bukan manfaat fungsi Excel dalam pengolahan dan perhitungan data terstruktur.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (428,24,126,'jadi kita mengunakan sum untuk mengitung seluruh total harga =sum(....)',NULL,2.5,'2026-09-15 00:00:25.000','2026-09-15 00:00:41.000','Siswa tepat memilih fungsi SUM, namun tidak mencantumkan argumen rentang sel yang spesifik (=SUM(B2:B15)).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (429,24,108,'=data yang menyimpan nilai nilai atau file',NULL,1,'2026-09-15 00:00:25.000','2026-09-15 00:00:41.000','Penjelasan data terstruktur belum tepat dan tidak menyertakan contoh yang diminta.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (430,24,112,'-=max(....)\n-=min(....)',NULL,2.5,'2026-09-15 00:00:25.000','2026-09-15 00:00:41.000','Siswa sudah tahu fungsi MAX dan MIN, namun tidak mengisi argumen rentang sel di dalam kurung.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (431,24,111,'=average(....)',NULL,2.5,'2026-09-15 00:00:25.000','2026-09-15 00:00:41.000','Penggunaan fungsi AVERAGE sudah benar, tetapi belum menyertakan argumen rentang sel.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (432,24,114,'if',NULL,1,'2026-09-15 00:00:25.000','2026-09-15 00:00:41.000','Siswa hanya menuliskan kata \'if\' tanpa menyusun penulisan rumus sintaks IF secara lengkap.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (433,24,119,'=if(..>..,\'\'TUNTAS\'\',\'\'BELUM TUNTAS\'\')',NULL,0,'2026-09-15 00:00:25.000','2026-09-15 00:00:41.000','Jawaban tidak relevan. Siswa menuliskan rumus logis IF bukannya rumus statistik (SUM, AVERAGE, MIN, MAX).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (434,24,121,'RATA RATA STOK BUKA PERHARI 25 PER BUKU',NULL,0.5,'2026-09-15 00:00:25.000','2026-09-15 00:00:41.000','Siswa tidak menuliskan formula Excel yang diminta (=AVERAGE(A1:A5)) dan memberikan perhitungan manual yang kurang tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (435,24,118,'Sum : untuk mencari seluruh nilai\nAverage: untuk mencari rata-rata nilai\nmin : mencari nilai terkecil\nmax : mencari nilai terbesar',NULL,4.5,'2026-09-15 00:00:25.000','2026-09-15 00:00:41.000','Penjelasan untuk fungsi AVERAGE, MIN, dan MAX sudah tepat, sedangkan untuk SUM akan lebih sempurna jika dijelaskan sebagai fungsi untuk menjumlahkan nilai.');
