INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (497,12,117,'=average(SEL):,max:(SEL),min:(SEL)=if(<\\>nilai,\"keterangan,\",keterangan\"))))',NULL,2,'2026-09-15 00:14:52.000','2026-09-15 00:15:15.000','Siswa menyebutkan beberapa fungsi yang relevan (AVERAGE, MAX, MIN, IF), tetapi tidak menyebutkan SUM dan penulisan rumus masih keliru.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (498,12,113,'sum:untk menjumlahkan seluruh hasil\navaregae:untk mentukan nilai rata-rata\nmin:mencari nilai terkecil\nmax:mencari niali terbesar\n',NULL,5.5,'2026-09-15 00:14:52.000','2026-09-15 00:15:15.000','Penjelasan fungsi SUM, AVERAGE, MIN, dan MAX sudah tepat secara konsep, hanya terdapat sedikit kesalahan penulisan (typo).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (499,12,121,'=average(a2:b2,;avarage(a3:b3,;average(a4:b4,;average(a5:b5))))',NULL,1.5,'2026-09-15 00:14:52.000','2026-09-15 00:15:15.000','Siswa menggunakan fungsi AVERAGE, namun penulisan rumus bertingkat dan acuan selnya kurang tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (500,12,122,'=count(b5:b4)',NULL,0.5,'2026-09-15 00:14:52.000','2026-09-15 00:15:15.000','Jawaban kurang tepat karena menggunakan fungsi COUNT. Formula yang tepat adalah menggabungkan MAX dan MIN (=MAX(B1:B5)-MIN(B1:B5)).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (501,12,125,'terstukrtur:data yang menjelaskan secara tertata:membuat jadwal bersih rumh\n\n',NULL,0.5,'2026-09-15 00:14:52.000','2026-09-15 00:15:15.000','Jawaban belum sesuai dengan konsep tipe data dalam pemrograman seperti Integer, String, atau Boolean.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (502,12,127,'if:untk mentukan sutan pernyataan tapi memiliki syarat\n=if(>c5=75,\"lulus\",\"tidak lulus\")',NULL,4.5,'2026-09-15 00:14:52.000','2026-09-15 00:15:15.000','Siswa memahami fungsi IF dan contoh kasusnya di sekolah, namun ada sedikit kesalahan penulisan operator pembanding pada sintaksis.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (503,12,124,'range:pertemuan yang bedekatan yaitu sel(block sel)\na2:a3',NULL,4.5,'2026-09-15 00:14:52.000','2026-09-15 00:15:15.000','Pengertian range sebagai kumpulan/blok sel serta contoh penulisannya sudah tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (504,12,110,'=sum(80:75,;90;65,;85,)',NULL,2,'2026-09-15 00:14:52.000','2026-09-15 00:15:15.000','Siswa benar menggunakan fungsi SUM, tetapi penulisan sintaksis rentang nilai di dalam kurung masih keliru.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (505,12,119,'=sum(b2:b6)\n=average(b2:b6)\n=min(b2:b6)\n=max(b2;b6)',NULL,4.5,'2026-09-15 00:14:52.000','2026-09-15 00:15:15.000','Sebagian besar formula sudah sangat tepat, hanya ada sedikit kesalahan tanda pemisah (titik koma) pada rumus MAX.');
