INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (566,29,118,'a.menghitung seluruh jumlah\nb.average mencai nilai rata rata\nc.min mencari nilai palin kecil/rata rata paling kecil\nd. max mencari rata rata terkecil\n',NULL,2.5,'2026-09-15 00:14:59.000','2026-09-15 00:15:13.000','Siswa memahami fungsi SUM dan AVERAGE dengan baik, namun keliru memahami fungsi MIN dan MAX karena mengaitkannya dengan nilai rata-rata.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (567,29,125,'float menampung satu karakter tunggal\nstring menyimpan data',NULL,1,'2026-09-15 00:14:59.000','2026-09-15 00:15:13.000','Penjelasan float tidak tepat (tertukar dengan tipe char), penjelasan string terlalu umum, serta belum menyertakan contoh dalam kehidupan sehari-hari.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (568,29,124,'cell yang diblok untuk menghitung hasil',NULL,1.5,'2026-09-15 00:14:59.000','2026-09-15 00:15:13.000','Konsep range yang dijelaskan mendekati namun kurang presisi (seharusnya kumpulan dari beberapa sel), dan siswa tidak memberikan contoh penulisannya.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (569,29,122,'=max(B1:B6)\n=min(B1:B6',NULL,1.5,'2026-09-15 00:14:59.000','2026-09-15 00:15:13.000','Siswa menyebutkan fungsi MAX dan MIN, namun tidak mengombinasikannya dalam satu formula pengurangan (=MAX(B1:B5)-MIN(B1:B5)) dan range sel kurang tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (570,29,111,'=average(B1:B6)',NULL,5,'2026-09-15 00:14:59.000','2026-09-15 00:15:13.000','Penulisan rumus Excel untuk menghitung rata-rata menggunakan fungsi AVERAGE sudah tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (571,29,113,'sum : untuk menjumlahkan\naverage : mencari nilai rata  rata\nmin : mencari nilai rata rata terkecil\nmax : mencarin nilai rata rata terbesar',NULL,3,'2026-09-15 00:14:59.000','2026-09-15 00:15:13.000','Penjelasan fungsi SUM dan AVERAGE tepat, namun penjelasan MIN dan MAX kurang tepat karena menyebutkan nilai rata-rata.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (572,29,121,'=average(A1:A6',NULL,2,'2026-09-15 00:14:59.000','2026-09-15 00:15:13.000','Penggunaan fungsi AVERAGE sudah tepat, namun range sel yang digunakan salah (seharusnya B1:B5) dan terdapat kesalahan sintaks berupa kurangnya kurung tutup.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (573,29,127,'untuk menghitung cell  yang ada angka dan hurufnya\ncontoh : menghitung predikat',NULL,1.5,'2026-09-15 00:14:59.000','2026-09-15 00:15:13.000','Penjelasan cara kerja fungsi IF belum tepat (seharusnya untuk mengevaluasi kondisi logika), namun contoh kasus penggunaan di sekolah (penentuan predikat) sudah relevan.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (574,29,108,'data terstruktur artinya  data yang mempunyai tabel .Dan mempunyai cell ,baris, dan diatas ada nomor , untuk menetukan baris keberapa',NULL,2.5,'2026-09-15 00:14:59.000','2026-09-15 00:15:13.000','Siswa memahami representasi data terstruktur dalam bentuk baris dan kolom/tabel, tetapi belum memberikan contoh nyata data terstruktur.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (575,29,109,'data angka:data yang ada angka\ndata teks : data yang mempunyai teks\ndata boolean : data yang berisi tentang boolean',NULL,1,'2026-09-15 00:14:59.000','2026-09-15 00:15:13.000','Penjelasan masih bersifat mengulang pertanyaan (sirkular) dan belum menyertakan contoh konkret untuk masing-masing tipe data.');
