INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (636,13,111,'Rumus EXCEL yang digunakan untuk\nmenghitung adalah SUM.',NULL,0,'2026-09-15 00:16:37.000','2026-09-15 00:16:52.000','Siswa keliru menyebutkan fungsi; untuk menghitung nilai rata-rata seharusnya menggunakan fungsi AVERAGE, bukan SUM.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (637,13,115,'=IF(F13>=90, \"A\", IF(F13>=80, \"B\", IF(F13>=75, \"D\", IF(F13<=60, \"D\",\"D\"))))',NULL,1.5,'2026-09-15 00:16:37.000','2026-09-15 00:16:52.000','Siswa menuliskan fungsi IF bertingkat untuk konversi nilai huruf, bukan penentuan status kelulusan (Lulus/Tidak Lulus) berdasarkan syarat >=75.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (638,13,119,'A. Total Nilai : =SUM(B2:B6) \nB. Rata-rata Nilai : =AVERAGE(B2:B6)\nC. Nilai Terendah : =MIN(B2:B6)\nD. Nilai Tertinggi : =MAX(B2:B6)',NULL,5,'2026-09-15 00:16:37.000','2026-09-15 00:16:52.000','Jawaban siswa sangat tepat dan lengkap. Penulisan rumus beserta rentang sel (B2:B6) sudah sesuai untuk keempat pertanyaan.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (639,13,126,'=SUM(B2:B15)',NULL,6,'2026-09-15 00:16:37.000','2026-09-15 00:16:52.000','Penulisan rumus SUM dengan rentang sel B2:B15 sudah tepat dan sesuai dengan perintah soal.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (640,13,113,'SUM : Menjumlahkan\nAVERAGE : Mencari rata-rata\nMIN : Nilai Terendah\nMAX : Nilai Tertinggi',NULL,6,'2026-09-15 00:16:37.000','2026-09-15 00:16:52.000','Siswa dapat menjelaskan fungsi SUM, AVERAGE, MIN, dan MAX dengan singkat, jelas, dan tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (641,13,124,'Range adalah kumpulan suatu cell.\nContoh : Range digunakan dalam baris cell.\n',NULL,2.5,'2026-09-15 00:16:37.000','2026-09-15 00:16:52.000','Definisi range yang diberikan sudah cukup baik, tetapi contoh penulisan sintaks range (seperti A1:B5) belum ditampilkan.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (642,13,120,'SUM, AVERAGE, MIN, MAX digunakan dalam mengolah data, akan mempermudah hitungan dalam EXCEL.',NULL,2,'2026-09-15 00:16:37.000','2026-09-15 00:16:52.000','Siswa hanya menyebutkan satu alasan umum (mempermudah hitungan) dan belum menjelaskan setidaknya 2 alasan spesifik seperti efisiensi waktu dan akurasi data.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (643,13,114,'=IF(C2>= 75, \"LULUS\", \"TIDAK LULUS))',NULL,5,'2026-09-15 00:16:37.000','2026-09-15 00:16:52.000','Logika penulisan rumus IF sudah benar, namun terdapat sedikit kesalahan ketik (typo) pada tanda petik penutup teks \'TIDAK LULUS\'.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (644,13,116,'Karena, dengan menyelesaikan soal dengan data terstruktur, akan menjadi lebih mudah dan rapi.',NULL,2,'2026-09-15 00:16:37.000','2026-09-15 00:16:52.000','Penjelasan siswa masih terlalu umum dan belum menguraikan bagaimana fungsi Excel membantu pengolahan data terstruktur secara efektif.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (645,13,117,'1. Mengetahui Jumlah (SUM)\n2. Mengetahui Rata-rata (AVERAGE)\n3. Mengetahui Nilai Tertinggi (MAX)\n4. Mengetahui Nilai Terendah (MIN)',NULL,4,'2026-09-15 00:16:37.000','2026-09-15 00:16:52.000','Siswa menjawab 4 fungsi dengan benar (SUM, AVERAGE, MAX, MIN), namun belum mencantumkan fungsi IF untuk kebutuhan status kelulusan.');
