INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (706,16,124,'kumpulan beberapa cell\ncontoh:mengumpulkan beberapa cell',NULL,2.5,'2026-09-15 00:16:39.000','2026-09-15 00:16:56.000','Siswa sudah menjelaskan pengertian range dengan benar, tetapi belum memberikan contoh penulisan sintaks range yang tepat (misalnya A1:B5).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (707,16,116,'karena,dengan menyelesaikan persoalan data struktur mudah di mengerti dan terpahami.',NULL,1.5,'2026-09-15 00:16:39.000','2026-09-15 00:16:57.000','Penjelasan masih terlalu umum. Harap disosialisasikan kembali peran fungsi Excel dalam kecepatan, akurasi, dan otomatisasi pengolahan data terstruktur.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (708,16,111,'=AVERAGE(F15:F17)',NULL,5,'2026-09-15 00:16:39.000','2026-09-15 00:16:57.000','Jawaban siswa sangat tepat dan penulisan rumus AVERAGE sudah sesuai dengan sintaks Excel.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (709,16,125,'DATA STRUKTUR\nCONTOH:DATA NILAI SISWA\n\nDATA TEKS\nCONTOH:TEKS(\"INFORMATIKA\")\n\n\n',NULL,2,'2026-09-15 00:16:39.000','2026-09-15 00:16:57.000','Siswa hanya dapat menyebutkan satu tipe data (teks) yang relevan, namun konsep tipe data dasar lainnya (seperti Integer atau Boolean) belum tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (710,16,117,'1)MENGETAHUI JUMLAH(SUM)\n2)MENGETAHUI RATA RATA(AVERAGE)\n3)MENGETAHUI NILAI TERENDAH(MIN)\n4)MENGETAHUI NILAI TERTINGGI(MAX)',NULL,4,'2026-09-15 00:16:39.000','2026-09-15 00:16:57.000','Siswa menyebutkan 4 dari 5 fungsi yang diminta dengan benar (SUM, AVERAGE, MIN, MAX), tetapi belum menyebutkan fungsi IF untuk status kelulusan.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (711,16,115,'=IF(F15>=70,\"A\",IF(F15>70,\"B\",IF(F15>70, \"C\",IF))))',NULL,1,'2026-09-15 00:16:39.000','2026-09-15 00:16:57.000','Jawaban belum tepat karena tidak menentukan status kelulusan tiap siswa dan penulisan rumus logika IF tidak sesuai syarat kriteria (>=75).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (712,16,127,'=IF(F14:F17)',NULL,0.5,'2026-09-15 00:16:39.000','2026-09-15 00:16:57.000','Siswa belum menjelaskan cara kerja fungsi IF maupun contoh kasus di sekolah, hanya menuliskan rumus yang tidak lengkap.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (713,16,114,'=IF(F16>=80,\"LULUS\",IF(F16>80,\"TIDAK LULUS\"))))',NULL,1.5,'2026-09-15 00:16:39.000','2026-09-15 00:16:57.000','Rumus kurang tepat. Sel yang dirujuk tidak sesuai (seharusnya C2), batas nilai kelulusan keliru (seharusnya >=75), dan penggunaan struktur IF berlebihan.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (714,16,108,'data struktur adalah data yang menyelesaikan kondisi tertentu.',NULL,1,'2026-09-15 00:16:39.000','2026-09-15 00:16:57.000','Pengertian data terstruktur belum tepat dan siswa belum mencantumkan contoh data terstruktur.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (715,16,122,'120\\150\\90\\200\\140',NULL,0,'2026-09-15 00:16:39.000','2026-09-15 00:16:57.000','Siswa belum menuliskan formula Excel yang diminta (seharusnya =MAX(B1:B5)-MIN(B1:B5)), hanya mendaftar kembali data angka.');
