INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (776,27,114,'=IF(C2>=75,\"LULUS\",IF(C2<75,\"TIDAK LULUS\",))',NULL,5,'2026-09-15 00:16:41.000','2026-09-15 00:16:55.000','Siswa memahami konsep logika IF, tetapi sintaks sedikit berlebihan (nested IF tidak diperlukan untuk 2 kondisi) dan ada kesalahan tanda koma di akhir.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (777,27,126,'=SUM(B2:B15)',NULL,6,'2026-09-15 00:16:41.000','2026-09-15 00:16:55.000','Jawaban sangat tepat, penulisan rumus fungsi SUM dan rentang sel sudah benar.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (778,27,127,'IF digunakan dalam penulisan rumus di excel  misalnya mencari nilai atau predikat nilai contoh:\n=IF(C2>=90<\"A\",DST).',NULL,2,'2026-09-15 00:16:41.000','2026-09-15 00:16:55.000','Penjelasan konsep fungsi IF masih kurang lengkap dan penulisan sintaks contoh rumus tidak valid.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (779,27,115,'KARENA DI KETENTUANNYA JIKA DIATAS ATAU SAMA DENGAN 75 ITU LULUS JADI:\nANI:LULUS\nBENI:TIDAK LULUS\nCICI:LULUS\nDONI:LULUS',NULL,4.5,'2026-09-15 00:16:41.000','2026-09-15 00:16:55.000','Siswa berhasil menentukan status kelulusan dengan tepat sesuai kriteria, namun tidak menyertakan penulisan formula IF secara eksplisit.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (780,27,117,'SUM-AVERAGE-MAX-MIN-DAN IF',NULL,5,'2026-09-15 00:16:41.000','2026-09-15 00:16:55.000','Jawaban sangat baik, seluruh fungsi Excel yang diminta telah disebutkan dengan benar.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (781,27,108,'Terstruktur merupakan data yang telah di susun dengan rapi agar pembaca tidak kebingungan saat di suruh menjelaskan .',NULL,2,'2026-09-15 00:16:41.000','2026-09-15 00:16:55.000','Pengertian data terstruktur kurang tepat secara konsep dan siswa tidak memberikan contoh yang diminta.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (782,27,112,'=MAX(C3:D5)\n=MIN(C3:D5)',NULL,5,'2026-09-15 00:16:41.000','2026-09-15 00:16:55.000','Penulisan rumus MAX dan MIN sudah tepat sesuai dengan kaidah penulisan fungsi di Excel.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (783,27,121,'=AVERAGE(A1:A5)',NULL,3.5,'2026-09-15 00:16:41.000','2026-09-15 00:16:55.000','Fungsi AVERAGE yang digunakan sudah tepat, namun referensi kolom keliru (menggunakan A1:A5 padahal soal menyebutkan B1:B5).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (784,27,124,'RANGE MERUPAKAN GABUNGAN DARI BEBERAPA CELL\nCONTOH:\n(C12:F15)',NULL,5,'2026-09-15 00:16:41.000','2026-09-15 00:16:55.000','Pengertian range dan contoh penulisannya sudah tepat dan jelas.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (785,27,120,'1.Agar kita bisa menghitung dengan lebih mudah dan hemat waktu\n2.danjuga perhitungan manual membuat pikiran menjadi banyak. Jadi agar kita lebih fokus kepada satu kerjaan saja disarankan menggunakan rumus excel saja.',NULL,4.5,'2026-09-15 00:16:41.000','2026-09-15 00:16:55.000','Siswa memberikan 2 alasan logis terkait efisiensi waktu dan pengurangan beban/kesalahan hitung manual.');
