INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1057,19,108,'DATA TERSTRUKTUR SECARA TEROGANISASI DENGAN FORMAT TERTENTU DAN DATA YANG TERSUSUN RAPI DALAM BARIS DAN KOLOM.',NULL,3.5,'2026-09-15 00:25:57.000','2026-09-15 00:26:12.000','Penjelasan mengenai data terstruktur sudah benar, namun siswa belum mencantumkan contoh yang diminta pada soal.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1058,19,115,'=IF(80\", \"A\"(75\", \"B\"(>75\")))',NULL,1,'2026-09-15 00:25:57.000','2026-09-15 00:26:12.000','Penulisan sintaks logika IF belum tepat dan tidak menyelesaikan permintaan soal untuk menentukan status masing-masing siswa.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1059,19,118,' A.UNTUK MENAMBAH \nB.UNTUK MENCARI NILAI RATA-RATA\nC.UNTUK MENCARI NILAI TERKECIL MISAL NYA DALAM RAPOT\nD.UNTUK MENCARI NILAI TERTINGGI ',NULL,4.5,'2026-09-15 00:25:57.000','2026-09-15 00:26:12.000','Penjelasan untuk keempat perintah secara umum sudah benar. Penjelasan fungsi SUM dapat disempurnakan lagi dengan istilah menjumlahkan data.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1060,19,111,'=AVERAGE(C2:C5)',NULL,5,'2026-09-15 00:25:57.000','2026-09-15 00:26:12.000','Rumus Excel untuk menghitung nilai rata-rata sudah sangat tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1061,19,126,'=SUM(B2:B15)',NULL,6,'2026-09-15 00:25:57.000','2026-09-15 00:26:12.000','Penulisan rumus SUM dengan rentang sel B2:B15 sudah sangat tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1062,19,112,'=MAX(C2:C5)/MIN(C2:C5)',NULL,3,'2026-09-15 00:25:57.000','2026-09-15 00:26:12.000','Penggunaan fungsi MAX dan MIN serta rentang sel sudah benar, namun sebaiknya dipisahkan menjadi dua rumus terpisah daripada digabungkan dengan operator pembagian.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1063,19,110,'=SUM(80:75:90:65:85)',NULL,1.5,'2026-09-15 00:25:57.000','2026-09-15 00:26:12.000','Penggunaan fungsi SUM sudah benar, namun sintaks pemisah angka/sel dan penulisan nilai data kurang tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1064,19,113,'SUM: FUNGSI NYA ADALA UNTUK MENAMBAH KAN ANGKA DALAM KOLOM.\nAVERAGE:UNTUK MENCARI NILAI RATA-RATA\nMAX:UNTUK MENCARI NILAI TERTINGGI',NULL,4,'2026-09-15 00:25:57.000','2026-09-15 00:26:12.000','Penjelasan untuk SUM, AVERAGE, dan MAX sudah tepat, tetapi siswa belum menjelaskan fungsi MIN.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1065,19,121,'=AVERAGE(A1:15)',NULL,1.5,'2026-09-15 00:25:57.000','2026-09-15 00:26:12.000','Fungsi AVERAGE yang digunakan sudah benar, tetapi penulisan rentang sel tidak valid (seharusnya B1:B5).');
