INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1127,30,119,'=max(b2:b6)',NULL,1.25,'2026-09-15 00:26:12.000','2026-09-15 00:26:28.000','Siswa hanya menjawab poin d (nilai tertinggi) dengan benar. Poin a (total), b (rata-rata), dan c (terendah) belum dijawab.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1128,30,124,'=max(c3:c2',NULL,1,'2026-09-15 00:26:12.000','2026-09-15 00:26:28.000','Siswa tidak menjelaskan pengertian Range dan penulisan contoh rumus belum lengkap/kurang tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1129,30,109,'data adalah penetapa nilai',NULL,0,'2026-09-15 00:26:12.000','2026-09-15 00:26:28.000','Jawaban siswa tidak relevan dengan pertanyaan mengenai penjelasan dan contoh tipe data angka, teks, dan Boolean.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1130,30,112,'max(B2:B2)',NULL,1,'2026-09-15 00:26:12.000','2026-09-15 00:26:28.000','Siswa menyebutkan fungsi MAX untuk nilai tertinggi tetapi sintaks sel belum tepat dan fungsi MIN untuk nilai terendah belum dituliskan.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1131,30,121,'=average(b5:b5',NULL,1.5,'2026-09-15 00:26:12.000','2026-09-15 00:26:28.000','Siswa sudah memilih fungsi AVERAGE dengan benar, namun rentang sel salah (seharusnya B1:B5) dan penulisan kurung belum lengkap.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1132,30,114,'ini adalaa nilai tertinggi',NULL,0,'2026-09-15 00:26:12.000','2026-09-15 00:26:28.000','Jawaban tidak relevan dengan permintaan penulisan rumus fungsi IF.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1133,30,126,'nilai 25.000',NULL,0,'2026-09-15 00:26:12.000','2026-09-15 00:26:28.000','Siswa tidak memberikan formula Excel penjumlahan (=SUM(B2:B15)) yang diminta.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1134,30,117,'=max(B2:B2)',NULL,1,'2026-09-15 00:26:12.000','2026-09-15 00:26:28.000','Siswa hanya menuliskan satu fungsi (MAX), sedangkan empat fungsi lain (SUM, AVERAGE, MIN, IF) belum disebutkan.');
