INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1196,28,116,'karena lebih rapi dan tersusun',NULL,1.5,'2026-09-15 00:28:20.000','2026-09-15 00:28:38.000','Jawaban siswa terlalu singkat dan hanya menyebutkan kerapian, belum menjelaskan efisiensi, akurasi, maupun otomatisasi pengolahan data terstruktur.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1197,28,119,'a.=if\nb.=average\nc.=min\nd.=max',NULL,1.5,'2026-09-15 00:28:20.000','2026-09-15 00:28:38.000','Penulisan rumus tidak lengkap karena tidak menyertakan rentang sel, serta penulisan fungsi untuk total nilai salah (menggunakan IF alih-alih SUM).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1198,28,110,'sum',NULL,1.5,'2026-09-15 00:28:20.000','2026-09-15 00:28:38.000','Siswa hanya menyebutkan nama fungsi dasar tanpa menyertakan sintaks rumus Excel yang lengkap seperti tanda sama dengan dan rentang sel.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1199,28,123,'ada kamera,bertatapan,dan lebih rapi',NULL,0,'2026-09-15 00:28:20.000','2026-09-15 00:28:38.000','Jawaban tidak relevan dengan pertanyaan mengenai bagian antarmuka (interface) Microsoft Excel.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1200,28,120,'alasan:\n1.lebih minin kesalahan\n2.lebih gampang ',NULL,3.5,'2026-09-15 00:28:20.000','2026-09-15 00:28:38.000','Siswa berhasil menyebutkan dua alasan yang relevan (meminimalisir kesalahan dan kemudahan), namun penjelasannya masih dapat diperjelas lagi.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1201,28,118,'a.sum berguna untuk penjumlahan\nb.average berguna untuk menghitung nilai rata-rata\nc.min untuk menghitung nilai terendah \nd.max untuk menghitung nilai terbesar',NULL,5,'2026-09-15 00:28:20.000','2026-09-15 00:28:38.000','Jawaban sangat baik, penjelasan fungsi SUM, AVERAGE, MIN, dan MAX dituliskan secara tepat dan rinci.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1202,28,111,'=average',NULL,2,'2026-09-15 00:28:20.000','2026-09-15 00:28:38.000','Penulisan rumus belum lengkap karena siswa tidak mencantumkan rentang sel (range) data yang dihitung.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1203,28,113,'Sum:penjumlahan\nAverage:nilai rata-rata\nMin:terendah\nMax:terbesar',NULL,6,'2026-09-15 00:28:20.000','2026-09-15 00:28:38.000','Jawaban tepat dan singkat dalam menjelaskan fungsi utama dari SUM, AVERAGE, MIN, dan MAX.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1204,28,115,'=if(ani>80,\"Lulus\",\"Tidak Lulus\",if(beni<60,\"Lulus\",Tidak Lulus\",if(cici>75,\"lulus\",\"Tidak Lulus\",if(doni>90,\"Lulus\",Tidak Lulus\"',NULL,2,'2026-09-15 00:28:20.000','2026-09-15 00:28:38.000','Siswa mencoba menyusun logika IF, namun terdapat kesalahan pada penggunaan operator relasional, logika syarat kelulusan, dan tanda petik/sintaksis.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1205,28,108,'data terstruktur adalah data yang  yang gampang di simpan ,rapi,dan diorganisasikan',NULL,3,'2026-09-15 00:28:20.000','2026-09-15 00:28:38.000','Pengertian data terstruktur yang disampaikan sudah cukup relevan, namun siswa belum mencantumkan contoh data terstruktur sesuai perintah soal.');
