INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1266,14,113,'sum berguna untuk mencari nilai jumblah keseluruhan.\naverage untuk mencari nilai rata rata.\nmin berguna untuk mencari nlai terkecil.\nmax berfungsi untuk mencari nilai terbesar.',NULL,6,'2026-09-15 00:29:30.000','2026-09-15 00:29:46.000','Siswa telah menjelaskan fungsi SUM, AVERAGE, MIN, dan MAX dengan tepat dan lengkap.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1267,14,110,'=sum(A1:A4) \nlalu tinggal klik enter',NULL,3.5,'2026-09-15 00:29:30.000','2026-09-15 00:29:46.000','Penggunaan fungsi SUM sudah benar, namun range sel (A1:A4) belum mencakup seluruh data 5 siswa (seharusnya 5 sel, misalnya A1:A5).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1268,14,112,'=max( A1:A6)\nlalu tinggal klik enter',NULL,2.5,'2026-09-15 00:29:30.000','2026-09-15 00:29:46.000','Siswa hanya menuliskan rumus untuk mencari nilai tertinggi (MAX), tetapi belum menuliskan rumus untuk nilai terendah (MIN).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1269,14,111,'=AVERAGE(A1:A6)\nlalu tinggal klik enter',NULL,5,'2026-09-15 00:29:30.000','2026-09-15 00:29:46.000','Penulisan rumus AVERAGE sudah tepat dan sesuai dengan perintah soal.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1270,14,114,'=IF(C2>=70,\"LULUS\", 70< \"TIDAK LULUS\"))))',NULL,2,'2026-09-15 00:29:30.000','2026-09-15 00:29:46.000','Siswa memahami penggunaan fungsi IF, namun penulisan sintaks, nilai acuan (seharusnya >=75), dan argumen kondisi salah belum tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1271,14,121,'=sum(A1:A9)',NULL,1,'2026-09-15 00:29:30.000','2026-09-15 00:29:46.000','Rumus kurang tepat. Untuk menghitung rata-rata seharusnya menggunakan fungsi AVERAGE dengan range sel B1:B5.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1272,14,109,'data angka adalah data yang menggunakan angka \ncontohny: nilai raport, tinggi badan, tanggal lahir dan sebagainya\ndata text adalah data yang menggunakan kata kata \ncontohnya:  daftar membeli di toko, daftar list barang yg ingin dibeli',NULL,3,'2026-09-15 00:29:30.000','2026-09-15 00:29:46.000','Siswa menjelaskan data angka dan teks beserta contohnya dengan baik, namun tidak menjelaskan konsep dan contoh data Boolean.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1273,14,127,'fungsinya untuk menghitung LULUS atau TIDAK LULUS cotoh kasusny ketika guru mau mencari lulus atau tidak lulus maka menggunakan IF',NULL,3,'2026-09-15 00:29:30.000','2026-09-15 00:29:46.000','Contoh kasus penggunaan di sekolah sudah relevan, namun cara kerja fungsi IF (mengevaluasi kondisi logis BENAR/SALAH) belum dijelaskan secara eksplisit.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1274,14,115,'80 (lulus)\n60(LULUS)\n75(LULUS)\n90(LULU)',NULL,1.5,'2026-09-15 00:29:30.000','2026-09-15 00:29:46.000','Status kelulusan untuk nilai 60 kurang tepat (seharusnya Tidak Lulus) dan siswa tidak mencantumkan formula/rumus IF Excel.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1275,14,117,'untuk mengetahui jumblah pake =sum(A1:A9)\nuntuk mencari nilai tertinggi menggunakan =max(A1:A9)\nuntuk mengetahui nilai terendah =min(A1:A12)\nuntuk status kelulusan =IF(A1>=75,\"LULUS\", \"TIDAK LULUS\"\n',NULL,4,'2026-09-15 00:29:30.000','2026-09-15 00:29:46.000','Siswa berhasil menjawab 4 dari 5 fungsi yang diminta (SUM, MAX, MIN, IF), tetapi lupa mencantumkan fungsi AVERAGE untuk nilai rata-rata.');
