INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1617,22,112,'=max(c5;c2)\n=sem(a5;a2',NULL,1,'2026-09-15 00:51:05.000','2026-09-15 00:51:19.000','Penulisan rumus belum tepat; penggunaan fungsi MIN ditulis \'=sem\' dan penggunaan rentang sel belum sesuai.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1618,22,108,'itu macam yang terratur atau yang diatur kaya kelompok tabel pokonya yang di atur secara tersunsun dengan rapi.',NULL,3.5,'2026-09-15 00:51:05.000','2026-09-15 00:51:19.000','Siswa memahami konsep dasar data terstruktur, namun penjelasan dan contoh dapat disempurnakan lagi.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1619,22,115,'BENI =IF(80,\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nANI=LULUS\nBENI=TIDAK LULUS\nCICI=LULUS\nDONI=LULUS\n\n\n\n\n\n\n',NULL,2.5,'2026-09-15 00:51:05.000','2026-09-15 00:51:19.000','Siswa berhasil menentukan status kelulusan tiap siswa secara manual, namun penulisan rumus/logika IF belum selesai.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1620,22,120,'ITU ADALAH OBJEC YAITU ADA SUM, AVERAGE, MIN, DAN MAX ITU ADALAH SUATU OBJEC UNTUK MENGETAHUI NILAI - NILAI',NULL,0.5,'2026-09-15 00:51:05.000','2026-09-15 00:51:19.000','Siswa belum menjelaskan alasan efisiensi/ketelitian fungsi otomatis, hanya menyebutkan nama-nama fungsi.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1621,22,121,'=AVERAGE(A1;):120,(A2;):150,(A3;)90,(A4;):200,(A5):140)))',NULL,1,'2026-09-15 00:51:05.000','2026-09-15 00:51:19.000','Siswa sudah mengetahui penggunaan fungsi AVERAGE, namun penulisan sintaks rumus/rentang sel masih salah.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1622,22,126,'=SUM(B2;\"B3;\"B4;\"B5 DAN SAMPAI SETERUSNYA SAMPAI 15',NULL,2,'2026-09-15 00:51:05.000','2026-09-15 00:51:19.000','Siswa mengetahui penggunaan fungsi SUM dan sel awal, tetapi belum memahami penulisan rentang sel (range) B2:B15.');
