INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1756,36,122,'=MAX(B2:B6)\n=MIN(B2:B6)',NULL,2,'2026-09-15 02:10:08.000','2026-09-15 02:10:23.000','Siswa belum menggabungkan fungsi menjadi satu formula selisih =MAX(B1:B5)-MIN(B1:B5) serta rentang sel yang digunakan kurang tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1757,36,114,'=IF(C2>75,\"LULUS\",\"TIDAK LULUS\")',NULL,4,'2026-09-15 02:10:08.000','2026-09-15 02:10:23.000','Rumus hampir tepat, namun operator logika yang digunakan seharusnya >= bukan > agar nilai 75 tetap dinyatakan lulus.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1758,36,124,'Range adalah kumpulan dari beberapa cell.\ncontoh:\nA1:A6',NULL,5,'2026-09-15 02:10:08.000','2026-09-15 02:10:23.000','Jawaban sangat tepat. Pengertian range dan contoh penulisannya sudah benar.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1759,36,108,'Data struktus adalah sebuah data yang memiliki struktur.\ncontoh:\ndata struktus belanja',NULL,1.5,'2026-09-15 02:10:08.000','2026-09-15 02:10:23.000','Penjelasan masih bersifat tautologi dan kurang menjelaskan konsep data terstruktur (data yang terorganisir dalam baris/kolom), serta contoh kurang spesifik.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1760,36,125,'1. data struktur\n2. data belajar',NULL,0,'2026-09-15 02:10:08.000','2026-09-15 02:10:23.000','Jawaban belum tepat. Tipe data dalam pemrograman contohnya adalah Integer, String, Boolean, atau Float.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1761,36,117,'sum fungsinya mencari jumlah.\naverage fungsinya mencari nilai rata rata.\nmax fungsinya mencari nilai terbesar.\nmin fungsinya mencari nilai terendah.\nif fungsinya mencari status kelulusan.',NULL,5,'2026-09-15 02:10:08.000','2026-09-15 02:10:23.000','Jawaban sangat baik dan tepat dalam menyebutkan kelima fungsi Excel yang diminta.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1762,36,116,'fungsinya bisa lebih cepat terselesaikan dan lebih rapi serta lebih gampang di mengerti.',NULL,3.5,'2026-09-15 02:10:08.000','2026-09-15 02:10:23.000','Jawaban sudah cukup baik dengan mengemukakan alasan kecepatan dan efisiensi, namun bisa diperjelas dengan alasan akurasi data.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1763,36,119,'A. =sum(B2:B6)\nB. =AVERAGE(B2:B6)\nC. =MIN(B2:B6)\nD. =MAX(B2:B6)',NULL,5,'2026-09-15 02:10:08.000','2026-09-15 02:10:23.000','Jawaban sangat tepat. Seluruh formula yang dituliskan sudah benar sesuai data pada sel.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1764,36,120,'1. Karena lebih gampang di mengerti\n2. hasilnya juga lebih cepat di dapat dari pada hitung manual.\n',NULL,3.5,'2026-09-15 02:10:08.000','2026-09-15 02:10:23.000','Siswa berhasil memberikan 2 alasan. Akan lebih sempurna jika menyertakan alasan meminimalkan kesalahan penghitungan (human error).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1765,36,115,'ANI =IF(80>75,\"LULUS\",\"TIDAK LULUS\")\nBENI =IF(60>75,\"LULUS\",\"TIDAK LULUS\")\nCICI =IF(75>75,\"LULUS\",\"TIDAK LULUS\")\nDONI =IF(90>75,\"LULUS\",\"TIDAK LULUS\")',NULL,3,'2026-09-15 02:10:08.000','2026-09-15 02:10:23.000','Penggunaan operator > kurang tepat karena menyebabkan siswa dengan nilai 75 (Cici) dianggap Tidak Lulus. Seharusnya menggunakan operator >=.');
