INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1832,45,118,'sum itu gunakan untuk menjumlahkan \naverage untuk mengetahui nilai rata-rata\nmin untuk mengetahui nilai terendah\nmax untuk mengetahui nilai tertinggi',NULL,5,'2026-09-15 02:11:22.000','2026-09-15 02:11:38.000','Jawaban sangat baik, lengkap, dan tepat dalam menjelaskan fungsi SUM, AVERAGE, MIN, dan MAX.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1833,45,115,'=IF(80,60,75,90>=75,\"LULUS\"\"TIDAK LULUS\")\n',NULL,1.5,'2026-09-15 02:11:22.000','2026-09-15 02:11:38.000','Siswa memahami penggunaan fungsi IF, tetapi sintaks penulisan rumusnya belum tepat karena memasukkan beberapa nilai sekaligus dalam satu kondisi.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1834,45,125,'menggunakan SUM untuk menghitung jumlah orang yang ada di sekotar kita\nmenggunakan AVERAGE untuk menghitung rata-rata orang di sekitar kita',NULL,0,'2026-09-15 02:11:22.000','2026-09-15 02:11:38.000','Jawaban tidak relevan. Siswa menuliskan fungsi Excel (SUM dan AVERAGE) bukannya tipe data pemrograman.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1835,45,117,'jumlah untuk mengetahui tentang jumlah siswa\nrata-tara untuk mengetahui  tentang nilai rata-rata siswa\nnilai tertinggi untuk mengetahui tentang nilai tertinggi\nnilai terendah untuk mengetahui tentang nilai terendah\nkalau kelulusan menggunakan rumus ',NULL,1,'2026-09-15 02:11:22.000','2026-09-15 02:11:38.000','Siswa belum menuliskan nama fungsi Excel yang diminta (seperti SUM, AVERAGE, MAX, MIN, IF), hanya mengulang frasa pada soal.');
