INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1900,43,125,'Integer untuk menyimpan data angka bilangan bulat negatif maupun positif contohnya menulis umur\n\nFloat untuk menyimpan desimal hingga 7 angka desimal contohnya menulis harga 1,75',NULL,5,'2026-09-15 02:12:32.000','2026-09-15 02:12:52.000','Jawaban sangat baik. Siswa dapat menyebutkan, menjelaskan, dan memberikan contoh tipe data Integer dan Float dengan tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1901,43,119,'=sum(B2:B6)\n=averageB2:B6)\n=min(B2:B6)\n=max(B2:B6)',NULL,4,'2026-09-15 02:12:32.000','2026-09-15 02:12:52.000','Jawaban hampir sempurna. Terdapat sedikit kesalahan pengetikan (kurang tanda kurung buka) pada rumus average.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1902,43,120,'1 Agar tidak terjadi kesalahan\n2 Lebih mudah dan efisien\n3 Tidak banyak memakan waktu',NULL,5,'2026-09-15 02:12:32.000','2026-09-15 02:12:52.000','Jawaban tepat. Siswa memberikan 3 alasan relevan mengenai efisiensi dan keakuratan penggunaan fungsi otomatis.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1903,43,109,'data angka adalah data yang berisi angka contoh 123\ndata teks adalah data yang berisi teks contohnya Halo!\nBoolean berisi nilai logika contohnya boolean= hujan is true',NULL,5,'2026-09-15 02:12:32.000','2026-09-15 02:12:52.000','Jawaban tepat. Siswa berhasil menjelaskan perbedaan data angka, teks, dan Boolean beserta contohnya.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (1904,43,113,'Sum= Untuk menjumlahkan \nAverage= Untuk menghitung rata rata\nMin= Untuk mencari nilai terendah\nMax= Untuk mencari nilai tertinggi',NULL,6,'2026-09-15 02:12:32.000','2026-09-15 02:12:52.000','Jawaban sangat baik. Penjelasan untuk keempat fungsi Excel (SUM, AVERAGE, MIN, MAX) sudah tepat dan lengkap.');
