INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2036,49,112,'=MAX(C2:C6)\n=MIN(C2:C6)\n',NULL,5,'2026-09-15 02:19:39.000','2026-09-15 02:20:12.000','Siswa menjawab dengan sangat baik dan penulisan rumus MAX serta MIN sudah tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2037,49,119,'A.=SUM(B2:B5)\nB=AVERAGE(B2:B5)\nC=MIN(B2:B5)\nD=MAX(B2:B5)\n',NULL,3.5,'2026-09-15 02:19:39.000','2026-09-15 02:20:12.000','Fungsi yang digunakan sudah benar (SUM, AVERAGE, MIN, MAX), namun rentang sel kurang tepat (seharusnya B2:B6).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2038,49,125,'1.DATA TRSETURTURUK\n2.DATA  GAMEN',NULL,0.5,'2026-09-15 02:19:39.000','2026-09-15 02:20:12.000','Jawaban belum tepat. Tipe data pemrograman yang dimaksud seperti Integer, String, atau Boolean beserta contohnya belum dijelaskan.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2039,49,110,'=SUM(C2:C5)',NULL,3.5,'2026-09-15 02:19:39.000','2026-09-15 02:20:12.000','Penggunaan fungsi SUM sudah benar, namun rentang sel untuk 5 data siswa seharusnya C2:C6.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2040,49,114,'=IF(C2<75)\",TIDAK LULUS\",LULUS',NULL,2,'2026-09-15 02:19:39.000','2026-09-15 02:20:12.000','Siswa memahami konsep fungsi IF, namun penulisan sintaks rumus dan penempatan tanda petik/kurung masih keliru.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2041,49,126,'=SUM(A2:B15)\n',NULL,4,'2026-09-15 02:19:39.000','2026-09-15 02:20:12.000','Penggunaan fungsi SUM sudah benar, tetapi rentang kolom seharusnya hanya B2:B15, bukan mencakup kolom A.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2042,49,117,'=SUM\n=AVERAGE\n=MAX\n=MIN\n=IF\n',NULL,5,'2026-09-15 02:19:39.000','2026-09-15 02:20:12.000','Jawaban sangat baik. Siswa berhasil mengidentifikasi kelima fungsi Excel yang diminta dengan tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2043,49,118,'A.SUM  di gunakan untuk menghitung nilay\nB.AVERAGE di gunakan untuk mencari nilay rata rata\nC.MIN di gunakan untuk mencari nilay trerendah\nD.MAX di gunakan untuk mencari  nilay  tretingi',NULL,4,'2026-09-15 02:19:39.000','2026-09-15 02:20:12.000','Penjelasan AVERAGE, MIN, dan MAX sudah tepat. Penjelasan untuk SUM perlu ditambahkan kata \'menjumlahkan\' agar lebih spesifik.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2044,49,109,'data angka  sesuatu yang bisa aja\ndata teks data yang basa kita simpan\n',NULL,1,'2026-09-15 02:19:39.000','2026-09-15 02:20:13.000','Penjelasan masih kurang tepat dan sangat terbatas. Data Boolean serta contoh untuk tiap tipe data belum dituliskan.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2045,49,122,'=AVERSGE(B2:B6)',NULL,0.5,'2026-09-15 02:19:39.000','2026-09-15 02:20:13.000','Jawaban belum tepat. Untuk mencari selisih terbanyak dan tersedikit seharusnya menggunakan kombinasi rumus =MAX(B1:B5)-MIN(B1:B5).');
