INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2106,42,121,'=Average(B1:B5)',NULL,5,'2026-09-15 02:21:44.000','2026-09-15 02:21:58.000','Jawaban sangat tepat. Siswa menuliskan rumus AVERAGE dengan penggunaan rentang sel yang benar.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2107,42,108,'Data terstruktur adalah data yang tersusun secara teratur dan gampang di terorganisasi.\ncontohnya: tabel',NULL,4.5,'2026-09-15 02:21:44.000','2026-09-15 02:21:58.000','Jawaban sudah baik dan memahami konsep data terstruktur serta memberikan contoh yang relevan, meskipun penjelasannya masih tergolong singkat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2108,42,111,'=Average(B2:B15)',NULL,5,'2026-09-15 02:21:44.000','2026-09-15 02:21:58.000','Jawaban tepat. Penulisan sintaks rumus AVERAGE sudah benar.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2109,42,112,'=Max(C2:C6)\n=Min(C2:C6)',NULL,5,'2026-09-15 02:21:44.000','2026-09-15 02:21:58.000','Jawaban sangat tepat. Rumus MAX dan MIN dituliskan dengan benar dan lengkap.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2110,42,120,'1.Karena lebih gampang untuk melihat hasilnya.\n2.Karena kita tidak usah repot-repot menghitungnya secara manual.',NULL,3.5,'2026-09-15 02:21:44.000','2026-09-15 02:21:58.000','Siswa berhasil memberikan 2 alasan secara sederhana, namun belum menyebutkan konsep penting seperti efisiensi waktu/kecepatan dan akurasi (mencegah kesalahan hitung).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2111,42,115,'=IF(C2>75,\"LULUS\",\"TIDAK LULUS\")\n',NULL,2.5,'2026-09-15 02:21:44.000','2026-09-15 02:21:58.000','Jawaban kurang tepat. Operator logika yang digunakan kurang pas (menggunakan > bukan >=) dan belum menuliskan penentuan status kelulusan untuk masing-masing siswa.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2112,42,114,'=IF(C2>75,\"LULUS\",IF(C2<75,\"TIDAK LULUS\"))',NULL,2.5,'2026-09-15 02:21:44.000','2026-09-15 02:21:58.000','Rumus kurang tepat. Penggunaan operator logika salah (menggunakan > bukan >=) dan penambahan IF bertingkat membuat logika bernilai FALSE saat nilai siswa tepat 75.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2113,42,118,'a. SUM: Sum berguna untuk menjumlahkan nilai.\nb. AVERAGE: Average berguna untuk melihat nilai rata-rata.\nc. MIN: Min berguna untuk melihat nilai terendah.\nd. MAX: Max berguna untuk melihat nilai terbesar.',NULL,5,'2026-09-15 02:21:44.000','2026-09-15 02:21:58.000','Jawaban sangat lengkap dan tepat dalam menjelaskan fungsi dari SUM, AVERAGE, MIN, dan MAX.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2114,42,110,'=Sum(C2:C6)',NULL,5,'2026-09-15 02:21:44.000','2026-09-15 02:21:58.000','Jawaban tepat. Rumus SUM dan rentang sel yang dituliskan sudah benar.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2115,42,109,'Perbedaannya: Data angka itu terdiri dari angka seperti 1,2,3,4,5,6 dan seterusnya. Contoh: 3+3=\n\nKalo data teks itu isinya teks atau kalimat. Contoh: Hai nama gue bla bla bla.\n\nKalo data boolean itu menjelaskan tentang true atau false. =If(R4>01,/;',NULL,3,'2026-09-15 02:21:44.000','2026-09-15 02:21:58.000','Siswa memahami konsep dasar ketiga tipe data, namun bahasa yang digunakan sangat informal dan contoh data Boolean terpotong/kurang tepat.');
