INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2177,33,113,'SUM UNTUK JUMLAH NILAI\nAVERAGE UNTUK RATA-RATA NILAI\nMIN UNTUK NILAI TERRENDAH\nMAX UNTUK NILAI TERTINGGI',NULL,6,'2026-09-15 02:23:42.000','2026-09-15 02:24:20.000','Siswa dapat menjelaskan fungsi SUM, AVERAGE, MIN, dan MAX dengan tepat dan jelas.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2178,33,123,'3 BAGIAN:\n1.) LAYAR\n2.) KAMERA\n3.) KEYBOARD\n\nINTERFACE BERFUNGSI UNTUK SAAT LAGI UJIAN DARING DARI RUMAH, GURU BISA MELIHAT WAJAH KITA',NULL,0,'2026-09-15 02:23:42.000','2026-09-15 02:24:20.000','Jawaban tidak relevan dengan konsep antarmuka (interface) Microsoft Excel.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2179,33,124,'RANGE ADALAH KUMPULAN BEBERAPA SEL YANG DIGABUNG MENJADI SATU\n',NULL,2.5,'2026-09-15 02:23:42.000','2026-09-15 02:24:20.000','Siswa cukup memahami pengertian range, namun belum memberikan contoh penulisannya (seperti A1:B5) sesuai instruksi soal.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2180,33,121,'=AVERAGE(B1:B5)',NULL,5,'2026-09-15 02:23:42.000','2026-09-15 02:24:20.000','Formula AVERAGE yang dituliskan siswa sudah tepat untuk menghitung rata-rata data dari sel B1 sampai B5.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2181,33,122,'=MAX(B2:B6)\n=MIN(B2:B6)',NULL,1.5,'2026-09-15 02:23:42.000','2026-09-15 02:24:20.000','Siswa menggunakan fungsi MAX dan MIN dengan range sel yang kurang tepat (seharusnya B1:B5) dan belum menggabungkannya ke dalam satu rumus pengurangan selisih.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2182,33,111,'=AVERAGE(B2:B15)',NULL,5,'2026-09-15 02:23:42.000','2026-09-15 02:24:20.000','Penulisan rumus AVERAGE oleh siswa sudah tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2183,33,115,'=IF(80>75,\"TUNTAS\",\"GAGAL\")\n=IF(60>75,\"TUNTAS\",\"GAGAL\")\n=IF(70>75,\"TUNTAS\",\"GAGAL\")\n=IF(90>75,\"TUNTAS\",\"GAGAL\")',NULL,3,'2026-09-15 02:23:42.000','2026-09-15 02:24:20.000','Siswa memahami struktur fungsi IF, namun operator yang digunakan kurang tepat (seharusnya >=) dan terdapat kesalahan input nilai untuk Cici.');
