INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2386,34,126,'=SUM(B2:B15)\n',NULL,6,'2026-09-15 02:25:51.000','2026-09-15 02:26:12.000','Penulisan rumus SUM sudah sangat tepat dan sesuai dengan perintah soal.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2387,34,110,'=SUM(C2:C6)',NULL,5,'2026-09-15 02:25:51.000','2026-09-15 02:26:12.000','Penulisan rumus Excel untuk menghitung jumlah seluruh nilai sudah benar.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2388,34,118,'SUM berfungsi untuk menjumlahkan seluruh nilai\nAVERAGE berfungsi untuk mencari rata-rata nila\nMIN berfungsi untuk mencari nilai terkecil\nMAX berfungsi untuk mencari nilai terbesar',NULL,5,'2026-09-15 02:25:51.000','2026-09-15 02:26:12.000','Penjelasan mengenai fungsi SUM, AVERAGE, MIN, dan MAX disampaikan dengan jelas dan tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2389,34,119,'=SUM(B2:B6\n=AVERAGE(B2:B6)\n=MIN(B2:B6)\n=MAX(B2:B6)',NULL,4.5,'2026-09-15 02:25:51.000','2026-09-15 02:26:12.000','Jawaban sudah sangat baik dan tepat, hanya terdapat sedikit kekurangan berupa tanda kurung tutup pada formula SUM.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2390,34,116,'KARENA DATA TERSTRUKTUR BERKAITAN DENGAN TABEL UNTUK MENGHITUNG DATA',NULL,2.5,'2026-09-15 02:25:51.000','2026-09-15 02:26:12.000','Jawaban cukup relevan tetapi penjelasan mengenai manfaat penggunaan fungsi Excel untuk efisiensi dan akurasi data terstruktur masih belum lengkap.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2391,34,115,'=IF(80>=75,\"LULUS\",TIDAK LULUS\",60<=75,\"LULUS\",\"TIDAK LULUS\",75>=75,\"LULUS\",\"TIDAK LULUS\",90>=75,\"LULUS\",\"TIDAK LULUS\")',NULL,2,'2026-09-15 02:25:51.000','2026-09-15 02:26:12.000','Sintaks penulisan logika IF belum tepat sesuai aturan penulisan formula Excel, meskipun logika penentuannya sudah dicoba dijawab.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2392,34,108,'DATA TERSTRUKTUR ADALAH DATA YANG MENGGUNAKAN FORMAT PADA EXCEL CONTOHNYA DATA SISWA,DATA KEUANGAN, DATA PENILAIAN',NULL,3.5,'2026-09-15 02:25:51.000','2026-09-15 02:26:12.000','Pengertian data terstruktur masih terlalu sederhana, namun contoh yang diberikan sudah tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2393,34,123,'1. LAYAR\n2. KEYBOARD\n3. KAMERA\n\nFUNGSINYA ADALAH UNTUK MEMBAHAS PELAJARAN ATAU MENGERJAKAN TUGAS DALAM MICROSOFT EXCEL.',NULL,0,'2026-09-15 02:25:51.000','2026-09-15 02:26:12.000','Jawaban kurang tepat. Perangkat yang disebutkan adalah perangkat keras (hardware), bukan elemen antarmuka Microsoft Excel seperti Ribbon, Formula Bar, atau Sheet.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2394,34,121,'=AVERAGE(B2:B6)',NULL,3,'2026-09-15 02:25:51.000','2026-09-15 02:26:12.000','Penggunaan fungsi AVERAGE sudah tepat, namun rentang sel yang dimasukkan kurang tepat (seharusnya B1:B5 sesuai keterangan soal).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2395,34,112,'=MAX(C2:C6)\n=MIN(C2:C6)',NULL,5,'2026-09-15 02:25:51.000','2026-09-15 02:26:12.000','Penulisan rumus Excel untuk mencari nilai tertinggi (MAX) dan terendah (MIN) sudah tepat.');
