INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2526,46,118,'A.SUM UNTUK JUMLAH NILAI \nB.AVERAGE UNTUK MENGETAHUI NILAIRATA-RAT\nC.MIN UNTUK MENGETAHUI NILAI TERRENDAH\nD.MAX UNTUK MENGETAHUI NILAI TERTINGGI\n',NULL,5,'2026-09-15 02:28:08.000','2026-09-15 02:28:25.000','Jawaban sangat tepat, menjelaskan fungsi SUM, AVERAGE, MIN, dan MAX dengan benar dan jelas.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2527,46,117,'SUM UNTUK MENJUMLAH KAN \nAVERAGE UNTUK NILAI RATA-RATA\nMAX NILAI TERTINGGI\nMIN UNTUK NILAI TERRENDAH\n\"TUNTAS\",\"GAGAL\"',NULL,4,'2026-09-15 02:28:08.000','2026-09-15 02:28:25.000','Siswa menyebutkan fungsi SUM, AVERAGE, MAX, dan MIN dengan tepat, namun belum menuliskan nama fungsi IF untuk kelulusan.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2528,46,108,'DATA TERSTRUKTUR ADALAH DATA YANG DISUSUN SECARA TERSTRUKTUR',NULL,1,'2026-09-15 02:28:08.000','2026-09-15 02:28:25.000','Penjelasan masih bersifat tautologi (memutar kata) dan siswa belum memberikan contoh data terstruktur.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2529,46,120,'KARENA LEBIH GAMPANG DAN MUDAH UNTUK DI INGAT \nDAN SECARA LANGSUNG KITA MENGETAGUI BAHASA INGGRIS\n',NULL,1,'2026-09-15 02:28:08.000','2026-09-15 02:28:25.000','Alasan yang diberikan belum relevan dengan konsep pengolahan data besar, seperti efisiensi waktu dan akurasi.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2530,46,126,'=(JUMLAH TOTAL SEMUA NYA)',NULL,0,'2026-09-15 02:28:08.000','2026-09-15 02:28:25.000','Rumus tidak tepat. Penulisan yang benar adalah =SUM(B2:B15).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2531,46,112,'MAX DAN MIN',NULL,2,'2026-09-15 02:28:08.000','2026-09-15 02:28:25.000','Siswa sudah mengetahui nama fungsi MAX dan MIN, namun belum menuliskan bentuk rumus Excel lengkap.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2532,46,110,'=(TOTAL SEMUA JUMLAH)',NULL,0,'2026-09-15 02:28:08.000','2026-09-15 02:28:25.000','Penulisan rumus tidak sesuai dengan sintaks Excel. Seharusnya menggunakan fungsi SUM.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2533,46,109,'DATA ANGKA HANYA BERISI ANGKA\nDATA TEKS HANYA BERISI HURUF\nDATA BOOLEAN ',NULL,1.5,'2026-09-15 02:28:08.000','2026-09-15 02:28:25.000','Penjelasan data angka dan teks sangat singkat, data Boolean belum dijelaskan, serta belum menyertakan contoh.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2534,46,122,'=(><B1=120 B2=150 B3=90 B4=200)',NULL,0,'2026-09-15 02:28:08.000','2026-09-15 02:28:25.000','Kombinasi formula belum tepat. Formula yang benar adalah =MAX(B1:B5)-MIN(B1:B5).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2535,46,115,'=IF(80>75\"TUNTAS\",\"GAGAL\")\n=IF(60>75\"TUNTAS\",\"GAGAL\")\n=IF(75>75\"TUNTAS\",\"GAGAL\")\n=IF(90>75\"TUNTAS\",\"GAGAL\")\n',NULL,3.5,'2026-09-15 02:28:08.000','2026-09-15 02:28:25.000','Pemahaman logika IF sudah cukup baik, namun terdapat kekurangan sintaks pemisah argumen dan operator perbandingan seharusnya >=.');
