INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2596,47,122,'=MAX(B1;B5)MIN(B1;B5)\nLALU DI ENTER\nSTOK TERSEDIKIT=HARI KE 3=90\nSTOK TERBANYAK=HARI KE 4=200 ',NULL,2,'2026-09-15 02:29:10.000','2026-09-15 02:29:26.000','Siswa berhasil mengidentifikasi nilai terbanyak dan tersedikit secara manual, namun penulisan rumus kombinasi (=MAX(B1:B5)-MIN(B1:B5)) belum tepat karena tidak ada operator pengurangan dan penggunaan titik dua untuk rentang data.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2597,47,114,'=IF(C2>=75 \" \', \"(LULUS/TIDAK LULUS)',NULL,2,'2026-09-15 02:29:10.000','2026-09-15 02:29:26.000','Siswa memahami penggunaan fungsi IF dan kondisi >=75, namun penulisan sintaks rumus Excel belum benar.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2598,47,113,'SUM:UNTUK RATA RATA NILAI \nAVERAGE:TOTAL NILAI\nMAX:NILAI TERTINGGI\nMIN:NILAI TERENDAH ',NULL,3,'2026-09-15 02:29:10.000','2026-09-15 02:29:26.000','Penjelasan fungsi MAX dan MIN sudah tepat, namun penjelasan SUM dan AVERAGE terbalik.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2599,47,123,'KEYBOARD \nMOUS\nLAYAR \n\nINTERFACE BERGUNA UNTUK MENUJUKAN KEGUNAAN  SERTA MENUJUKAN LAYAR BERGAMBAR YANG SIAP MEMBANTU KITA MENGERJAKAN SUATU TUGAS DEGAN KELEBIHAN DAPAT MELIHAT SECARA LANGSUNG DAN SECARA MANDIRI CARA KERJA DI BANTU OLEH MESIN KOMPUTER .',NULL,1,'2026-09-15 02:29:10.000','2026-09-15 02:29:26.000','Siswa keliru menyebutkan perangkat keras (hardware) bukannya bagian dari antarmuka pengguna Microsoft Excel seperti Ribbon, Formula Bar, atau Worksheet.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2600,47,125,'DATA ANGKA :MNENGHITUNG ANGKA MEMASUKAN ANGKA \n\n\nDATA HURUF : MEMASUKAN HURUF DEGAN DATA TERKOTROL',NULL,2.5,'2026-09-15 02:29:10.000','2026-09-15 02:29:26.000','Siswa menyebutkan tipe data angka dan huruf, namun penjelasan dan contoh dalam kehidupan sehari-hari masih sangat terbatas dan belum jelas.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2601,47,109,'JIKA DATA TEKS  MENGOTROL TEKS  DAN SAMA DENGAN DATA ANGKA YANG MENGOTROL ANGKA  JIKA DATA BOOLEAN YANG MENGOTROL DATA YANG SEMAKIN DIPERJELAS .',NULL,1,'2026-09-15 02:29:10.000','2026-09-15 02:29:26.000','Siswa belum menjelaskan perbedaan ketiga tipe data secara tepat dan tidak memberikan contoh untuk masing-masing tipe data.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2602,47,112,'=MAX(C2;C6)\n=MIN(C2;C6)',NULL,3.5,'2026-09-15 02:29:10.000','2026-09-15 02:29:26.000','Penggunaan fungsi MAX dan MIN sudah benar, namun penulisan titik koma sebaiknya diganti dengan titik dua (:) untuk menunjukkan rentang/range sel.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2603,47,120,'KARENA LEBIH MEPERMUDAH DAN LEBIH SIMPEL',NULL,2,'2026-09-15 02:29:10.000','2026-09-15 02:29:26.000','Jawaban siswa terlalu singkat dan umum. Siswa belum menyebutkan 2 alasan spesifik seperti efisiensi waktu, akurasi/mencegah kesalahan hitung, atau otomatisasi saat data berubah.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2604,47,115,'\n=IF( ANI >= 80\",TUNTAS /TIDAK TUNTAS)\n=IF(BENI>= 60\",\"TUNTAS /TIDAK TUNTAS )\n=IF(CICI>=75\",\"TUNTAS/TIDAK TUNTAS) \n=IF(DONI>=90\",\"TUNTAS/TIDAK TUNTAS) ',NULL,1.5,'2026-09-15 02:29:10.000','2026-09-15 02:29:26.000','Siswa memahami konsep logika IF, tetapi penulisan sintaks rumus, pembanding nilai acuan (seharusnya >=75), dan pemisahan argumen keluaran masih belum tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2605,47,117,'=AVERAGE(JUMLAH RATA RATA )          =SUM(TOTAL NILAI )                         \n=MAX(NILAI TERTINGGI)\n=MIN(NILAI TERENDAH )\n=IF( NILAI STATUS KELULUSAN )\nAGAR MEMPERMUDAH MENGHITUNG NILAI ',NULL,4,'2026-09-15 02:29:10.000','2026-09-15 02:29:26.000','Siswa sudah tepat dalam menyebutkan kelima fungsi Excel yang dibutuhkan (SUM, AVERAGE, MAX, MIN, IF), meskipun struktur penulisan parameternya masih berupa deskripsi.');
