INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2807,44,116,'karena lebih mudah dipahami ',NULL,1.5,'2026-09-15 02:39:55.000','2026-09-15 02:40:08.000','Jawaban terlalu singkat dan belum menjelaskan alasan mendasar seperti efisiensi, keakuratan, dan pengolahan data terstruktur secara lengkap.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2808,44,121,'=AVERAGE(B1:B2:B3:B4:B5)\n',NULL,2.5,'2026-09-15 02:39:55.000','2026-09-15 02:40:08.000','Siswa sudah tepat menggunakan fungsi AVERAGE, namun penulisan rentang sel (range) kurang tepat (seharusnya B1:B5).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2809,44,123,'-SHEETS:lembaran kerja\n-SAFE:menyimpan\n-PAPER:kertas\n',NULL,1.5,'2026-09-15 02:39:55.000','2026-09-15 02:40:08.000','Siswa hanya menyebutkan Sheets dengan benar, sedangkan komponen antarmuka utama lainnya dan penjelasannya kurang tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2810,44,112,'=MAX(C2:C6)\n',NULL,2.5,'2026-09-15 02:39:55.000','2026-09-15 02:40:08.000','Siswa menuliskan rumus MAX dengan benar, namun belum menuliskan rumus MIN untuk nilai terendah.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2811,44,118,'-SUM: Jumbla Nilai\n-AVERAGE: Nilai Rata Rata\n-MIN: Nilai Terendah\n-MAX:Nilai Tertinggi',NULL,5,'2026-09-15 02:39:55.000','2026-09-15 02:40:08.000','Siswa berhasil menjelaskan fungsi utama keempat perintah pengolahan data dengan tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2812,44,117,'-MAX\n-MIN\n-AVERAGE\n-IF\n-SUM',NULL,5,'2026-09-15 02:39:55.000','2026-09-15 02:40:08.000','Siswa telah menyebutkan kelima fungsi Excel yang dibutuhkan dengan lengkap dan tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2813,44,109,'DATA ANGKA= 1,2,3,4,5\nDATA TESK= Hidup Jokowi\nBOOLEAN=0.9,6.7\n',NULL,1.5,'2026-09-15 02:39:55.000','2026-09-15 02:40:08.000','Siswa tidak memberikan penjelasan perbedaan, serta contoh data Boolean kurang tepat (seharusnya TRUE/FALSE).');
