INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2876,31,114,'=IF(C2>=75,\"LULUS\",IF(C2<=75,\"TIDAK LULUS\"))\n',NULL,4,'2026-09-15 02:40:10.000','2026-09-15 02:40:26.000','Siswa memahami penggunaan fungsi IF dan kondisi >=75, namun sintaksis nested IF kurang tepat karena menambahkan IF kedua yang tidak diperlukan dan overlapping pada nilai 75.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2877,31,123,'TABEL=UNTUK MENYUSUN DATA DENGAN TEROGARNISIR\nARRAY =KUMPULAN ELEMEN DATA DENGAN TIPE YANG SAMA\nCOUNT=UNTUK MENGHITUNG ANGKA DALAM KOLOM\n\n',NULL,1,'2026-09-15 02:40:10.000','2026-09-15 02:40:26.000','Siswa belum menyebutkan bagian utama antarmuka Microsoft Excel (seperti Ribbon, Formula Bar, Worksheet, Cell, dll), melainkan menyebutkan istilah fungsi dan tabel.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2878,31,111,'=AVERAGE(B2:B15)',NULL,5,'2026-09-15 02:40:10.000','2026-09-15 02:40:26.000','Jawaban sangat tepat. Rumus AVERAGE dituliskan dengan sintaksis dan rentang sel yang benar.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2879,31,127,'Caranya dengan melakukan pengujian berdasarkan kondisi\n\nContoh: =IF(C4>=70,\"LULUS\",IF(C4<=\"TIDAK LULUS\"))\n',NULL,4,'2026-09-15 02:40:10.000','2026-09-15 02:40:26.000','Penjelasan cara kerja fungsi IF sudah cukup benar, namun contoh sintaksis rumus IF masih memiliki kesalahan penulisan pada argumen kedua.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2880,31,108,'Adalah data yang disusun secara terorganisir dengan format tertentu\n\nTabel=untuk menyusun data dengan rapi',NULL,4.5,'2026-09-15 02:40:10.000','2026-09-15 02:40:26.000','Siswa dapat menjelaskan konsep data terstruktur dengan baik dan memberikan contoh format penyusunan data.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2881,31,110,'=SUM(C2:C6)',NULL,5,'2026-09-15 02:40:10.000','2026-09-15 02:40:26.000','Jawaban sangat tepat. Penggunaan fungsi SUM dan perkiraan rentang sel sudah benar.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2882,31,126,'=SUM(B2:B15)',NULL,6,'2026-09-15 02:40:10.000','2026-09-15 02:40:26.000','Jawaban sempurna. Penulisan rumus SUM untuk rentang B2:B15 sudah tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2883,31,116,'Karena membantu menghitung lebih efisien dan pengerjaaan dengan cepat',NULL,4,'2026-09-15 02:40:10.000','2026-09-15 02:40:26.000','Siswa dapat menjawab alasan utama penggunaan fungsi Excel (efisiensi dan kecepatan), meskipun penjelasan dapat diperluas sedikit lagi.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2884,31,115,'=IF(ANI>=75,\"LULUS\",\"TIDAK LULUS\",IF(DONI>=75,\"LULUS\",TIDAK LULUS\",IF(CICI>=75,\"LULUS\",\"TIDAK LULUS\",IF(BENI<=75,\"LULUS\",\"TIDAK LULUS\"))))',NULL,2,'2026-09-15 02:40:10.000','2026-09-15 02:40:26.000','Siswa mencoba menentukan status semua siswa, namun sintaksis formula IF beruntun kurang tepat dan penggunaan teks tanpa referensi sel/tanda petik yang salah.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (2885,31,122,'=MAX(B1:B5)-=MIN(B1:B5)',NULL,4,'2026-09-15 02:40:10.000','2026-09-15 02:40:26.000','Konsep penggabungan MAX dan MIN sudah sangat tepat, namun terdapat kelebihan tanda sama dengan (=) di tengah rumus (-=MIN).');
