INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (3287,38,125,'bolueen data yamg mengunakan pasport \nstring mempunyai data raport',NULL,1.5,'2026-09-15 04:58:41.000','2026-09-15 04:58:55.000','Siswa menyebutkan nama dua tipe data (boolean dan string) dengan cukup baik, namun penjelasan dan contoh dalam kehidupan sehari-hari belum tepat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (3288,38,120,'untuk mendapatkan nilai- nilai tertentu dalam computer tersebut',NULL,1,'2026-09-15 04:58:41.000','2026-09-15 04:58:55.000','Jawaban terlalu umum dan tidak menjawab minimal 2 alasan utama (seperti kecepatan/efisiensi dan akurasi/menghindari kesalahan manual).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (3289,38,123,'fungsinya untuk menjelaskan bagian-bagian',NULL,0.5,'2026-09-15 04:58:41.000','2026-09-15 04:58:55.000','Siswa belum menyebutkan 3 bagian utama antarmuka Microsoft Excel (seperti Ribbon, Formula Bar, Worksheet) beserta fungsinya.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (3290,38,115,'=IF(80=>75,\"LULUS\",TIDAK LULUS\"))))\n=IF(60=<75,\"LULUS\",TIDAK LULUS\"))))\n=IF(90=>75,\"LULUS\",TIDAK LULUS\"))))',NULL,2,'2026-09-15 04:58:41.000','2026-09-15 04:58:55.000','Siswa sudah memahami konsep logika IF, namun ada kesalahan sintaks (operator \'=>\' seharusnya \'>=\', tanda petik kurang), dan data siswa Cici terlewat.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (3291,38,124,'RANGE ADALAH SEBUAH KOLOM BARISAN TERDEKAT DEKAT BARIS BERBARIS',NULL,0.5,'2026-09-15 04:58:41.000','2026-09-15 04:58:55.000','Pengertian Range belum tepat (seharusnya kumpulan dari beberapa sel) dan siswa tidak memberikan contoh penulisannya.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (3292,38,114,'=IF(C2=>75,\"LULUS\",\"TIDAK LULUS\")))',NULL,4.5,'2026-09-15 04:58:41.000','2026-09-15 04:58:55.000','Logika penulisan rumus IF sudah tepat. Terdapat sedikit kesalahan penulisan sintaks operator \'=>\' yang seharusnya \'>=\' dan kelebihan kurung tutup.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (3293,38,118,'SUM MENJUMLAHKAN NILAH \nAVERAGE MERATAKAN NILAI RATA-RATA \nMIN MENEMUKAN NILAI TERENDAH\nMAX MENEMUKAN NILAI TERTINGI',NULL,5,'2026-09-15 04:58:41.000','2026-09-15 04:58:55.000','Sangat baik. Siswa berhasil menjelaskan fungsi utama dari SUM, AVERAGE, MIN, dan MAX dengan tepat dan jelas.');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (3294,38,117,'KEBUTUHAN NYA UNTUK MENENTUKAN NILAI-NILAI TERSEBUT \nDALAM PASPORT DAN LAIN LAINYA',NULL,0,'2026-09-15 04:58:41.000','2026-09-15 04:58:55.000','Jawaban tidak relevan dengan pertanyaan. Siswa tidak menyebutkan fungsi Excel yang diminta (SUM, AVERAGE, MAX, MIN, IF).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (3295,38,122,'=MIN(B1:120)\n=MIN(B2:150)\n=MIN(B3:90)\n=MIN(B4:200)',NULL,0.5,'2026-09-15 04:58:41.000','2026-09-15 04:58:55.000','Formula yang dituliskan belum tepat. Kombinasi yang benar seharusnya menggunakan pengulangan formula MAX dan MIN, yaitu =MAX(B1:B5)-MIN(B1:B5).');
INSERT INTO `jawaban_siswa` (`id`,`hasil_ujian_id`,`soal_id`,`jawaban_dipilih`,`is_benar`,`nilai_essay`,`created_at`,`updated_at`,`feedback_ai`) VALUES (3296,38,127,'=IF(60=<70,\"LULUS\",\"TIDAK LULUS\")))',NULL,1.5,'2026-09-15 04:58:41.000','2026-09-15 04:58:55.000','Siswa tidak memberikan penjelasan konsep cara kerja logika IF dan hanya memberikan contoh rumus yang masih memiliki kesalahan penulisan operator.');
